// Check for execution error
if ($input.item.json.exitCode !== 0) {
  throw new Error('extract_text.py failed (exit ' + $input.item.json.exitCode + '): ' + $input.item.json.stderr);
}

// Parse JSON output from extract_text.py
let extractData;
try {
  extractData = JSON.parse($input.item.json.stdout);
} catch (e) {
  throw new Error('Failed to parse extract_text.py JSON output: ' + e.message + '\nstdout: ' + $input.item.json.stdout.slice(0, 500));
}

if (!extractData.text || extractData.text.trim().length === 0) {
  throw new Error('Extracted text is empty for file: ' + (extractData.metadata && extractData.metadata.file_name || 'unknown'));
}

// Write text to a temp file to safely pass to chunk_text.py (avoids shell-escaping issues)
const os = require('os');
const fs = require('fs');
const path = require('path');
const tmpText = path.join(os.tmpdir(), 'n8n_text_' + Date.now() + '_' + Math.random().toString(36).slice(2) + '.txt');
fs.writeFileSync(tmpText, extractData.text, 'utf8');

return {
  json: {
    text: extractData.text,
    metadata: extractData.metadata,
    ocr_used: extractData.ocr_used || false,
    page_count: extractData.page_count || 1,
    _tmp_text: tmpText
  }
};

if ($input.item.json.exitCode !== 0) {
  throw new Error('chunk_text.py failed (exit ' + $input.item.json.exitCode + '): ' + $input.item.json.stderr);
}

let chunks;
try {
  chunks = JSON.parse($input.item.json.stdout);
} catch (e) {
  throw new Error('Failed to parse chunk_text.py JSON output: ' + e.message);
}

if (!Array.isArray(chunks) || chunks.length === 0) {
  throw new Error('chunk_text.py returned empty chunks array');
}

// Write chunks array to temp file for embed_chunks.py stdin
const os = require('os');
const fs = require('fs');
const path = require('path');
const tmpChunks = path.join(os.tmpdir(), 'n8n_chunks_' + Date.now() + '_' + Math.random().toString(36).slice(2) + '.json');
fs.writeFileSync(tmpChunks, JSON.stringify(chunks), 'utf8');

// Clean up text temp file
try { fs.unlinkSync($input.item.json._tmp_text); } catch(e) {}

return {
  json: {
    text: $input.item.json.text,
    metadata: $input.item.json.metadata,
    ocr_used: $input.item.json.ocr_used,
    page_count: $input.item.json.page_count,
    chunk_count: chunks.length,
    _tmp_chunks: tmpChunks
  }
};

if ($input.item.json.exitCode !== 0) {
  throw new Error('embed_chunks.py failed (exit ' + $input.item.json.exitCode + '): ' + $input.item.json.stderr);
}

let embeddedChunks;
try {
  embeddedChunks = JSON.parse($input.item.json.stdout);
} catch (e) {
  throw new Error('Failed to parse embed_chunks.py JSON output: ' + e.message);
}

if (!Array.isArray(embeddedChunks) || embeddedChunks.length === 0) {
  throw new Error('embed_chunks.py returned empty result');
}

// Build full payload for write_to_db.py
// Format: {text, metadata, ocr_used, page_count, chunks: [{chunk_index, chunk_text, char_count, token_estimate, embedding}]}
const payload = {
  text: $input.item.json.text,
  metadata: $input.item.json.metadata,
  ocr_used: $input.item.json.ocr_used || false,
  page_count: $input.item.json.page_count || 1,
  chunks: embeddedChunks
};

// Write full payload to temp file for write_to_db.py stdin
const os = require('os');
const fs = require('fs');
const path = require('path');
const tmpPayload = path.join(os.tmpdir(), 'n8n_payload_' + Date.now() + '_' + Math.random().toString(36).slice(2) + '.json');
fs.writeFileSync(tmpPayload, JSON.stringify(payload), 'utf8');

// Clean up chunks temp file
try { fs.unlinkSync($input.item.json._tmp_chunks); } catch(e) {}

return {
  json: {
    metadata: $input.item.json.metadata,
    chunk_count: embeddedChunks.length,
    _tmp_payload: tmpPayload
  }
};
